def seed_rows():
    for group, entries in GROUPS.items():
        for i,(name,cas,mw) in enumerate(entries,1):
            code = f'{group}{i:02}' if group.startswith('PBO-') else f'{group}-{i:02}'
            route = 'BOTH'
            if group in ('DA','DM','GR','PI','PS','IN','CAT','CL') or code in ('XL-01','XL-02'): route='N'
            if group in ('PBO-AP','PBO-DC','PAC','PAG'): route='P'
            yield dict(code=code, category=group, route=route, mw=mw,
                       identity=dict(name=name,cn_name=CN_NAMES[code],cas=cas,supplier='',grade=''),
                       source=('SDD v1.1工艺试剂，规格待核对' if code in ('IN-03','CAT-01','CL-01','AS-01','WP-01') else 'TCI A0743 / CAS 818-61-1，规格待核对' if code=='GR-04' else 'TCI T2040 / CAS 7719-09-7，规格待核对' if code=='RG-01' else '文档配方示例补充溶剂，待核对' if code=='SV-03' else 'SDD v1.0，待人工核对'))
